from .setups import RmodsConnectionsSetups
from ...exceptions import MissingUsernameInRuObjectError, MissingPasswordInRuObjectError
from taf.config.testline.lmi import SerialOverTcp, Remote, LMI, SerialOverHost
from taf.config.testline.info import info
from taf.config.testline.info.exceptions import UserNotDefinedForSWLine
from taf.config.testline import RU
from pathlib import Path
from yaml import safe_load
import random

ALL_RMODS = "All Rmods"


class RmodConfiguration:
    def __init__(self, init_ru_config: RU, custom_rmod_setup_yaml_path: str = None):
        self._init_ru = init_ru_config
        self._lmi = None
        self._lmi_ip = None
        self._lmi_ports = None
        self._serial_number = None
        self._type = None
        self._family = None
        self._username = None
        self._init_username = None
        self._password = None
        self._init_password = None
        self._legacy_lmi_config = None
        self._output_switch_seconds = None
        self._current_switch_slave_node_id = None
        self._slave_node_switch_cmd = None
        self._master_node_switch_cmd = None
        self._master_node_id = None
        self._switch_commands = None
        self._connected_rmod = None
        self._rmod_families = RmodsConnectionsSetups()
        self._custom_yaml_setup = Path(custom_rmod_setup_yaml_path) if custom_rmod_setup_yaml_path else None
        self._custom_setup = self._read_rmod_data()
        self._switch_nodes = True
        self._freeze_slave_node = False
        self._preserve_flags = True
        self._commands_after_connect = None
        self._commands_after_login_master = None
        self._commands_after_login_slave = None
        self._auto_snapshot = True
        self._critical_faults = [1112, 10004, 1384, 1149, 1103, 1255, 1288, 1405, 1463]
        self._normal_faults = {1309: 2}
        self._fh_interface = None
        self._proxy_vm_credentials = None
        self._switch_fhnet_container = None

    def __str__(self):
        return (
            "\nRmodConfiguration object with following parameters:\n"
            f"lmi: {self.lmi}\n"
            f"lmi_ip: {self.lmi_ip}\n"
            f"lmi_ports: {self.lmi_ports}\n"
            f"serial_number: {self.serial_number}\n"
            f"radio_type: {self.radio_type}\n"
            f"radio_family: {self.radio_family}\n"
            f"username: {self.username}\n"
            f"password: {self.password}\n"
            f"switch_nodes: {self.switch_nodes}\n"
            f"start_node_id_to_switch: {self.current_switch_slave_node_id}\n"
            f"freeze_slave_node_id_change: {self.freeze_slave_node}\n"
            f"switch_seconds: {self.output_switch_seconds}\n"
            f"preserve_flags: {self.preserve_flags}\n"
            f"auto_snapshot_on_fault: {self.auto_snapshot_on_fault}\n"
            f"critical_faults: {self.critical_faults}\n"
            f"normal_faults {{fid: snapshot_after_fault_visible minutes}}: {self.normal_faults}\n"
            f"Legacy (lmp_connection) TL __init__ used: {self._legacy_lmi_config}\n"
            f"Custom yaml file used: {self._custom_yaml_setup}\n"
        )

    @property
    def lmi(self):
        if self._lmi is None:
            if self._init_ru.lmi is None:
                self._legacy_lmi_config = True
                self._lmi = SerialOverTcp(
                    uart_mapping=[
                        Remote(addr=self.lmi_ip, port=int(port)) for port in self.lmi_ports if isinstance(port, int)
                    ]
                )
            else:
                self._lmi = self._init_ru.lmi
                self._legacy_lmi_config = False
        return self._lmi

    @property
    def lmi_ip(self):
        if self._lmi_ip is None:
            if self._init_ru.lmi is None:
                self._lmi_ip = self._init_ru.lmp_connection.addr
            elif isinstance(self._init_ru.lmi, LMI) or isinstance(self._init_ru.lmi, SerialOverHost):
                return None
            else:
                self._lmi_ip = (
                    self._init_ru.lmi.uart_mapping[0].addr
                    if (isinstance(self._init_ru.lmi.uart_mapping[0].addr, str))
                    else self._init_ru.lmi.uart_mapping[0].addr.v4
                )
        return self._lmi_ip

    @property
    def lmi_ports(self):
        if self._lmi_ports is None:
            if self._init_ru.lmi is None:
                self._lmi_ports = (
                    int(self._init_ru.lmp_connection.port),
                    int(self._init_ru.lmp_connection.username) if self._init_ru.lmp_connection.username else "",
                )
            else:
                self._lmi_ports = tuple([uart.port for uart in self._init_ru.lmi.uart_mapping])
        return self._lmi_ports

    @property
    def serial_number(self):
        if self._serial_number is None:
            self._serial_number = str(self._init_ru.serial_number)
        return self._serial_number

    @property
    def radio_type(self):
        if self._type is None:
            self._type = str(self._init_ru.radio_type)
        return self._type

    @property
    def radio_family(self):
        if self._family is None:
            for rmod_setup in self._rmod_families.setups:
                if self.radio_type in rmod_setup.product_names:
                    self._family = rmod_setup.program
                    self._connected_rmod = {self._family: rmod_setup}
                    break
                else:
                    self._family = "Unknown"
                    self._connected_rmod = {
                        self._family: [
                            unknown for unknown in self._rmod_families.setups if unknown.program == self._family
                        ][0]
                    }
        return self._family

    @property
    def username(self):
        if self._username is None:
            self._username, self._password = self._get_ru_user_and_password()
        return self._username

    @username.setter
    def username(self, value):
        self._username = value

    @property
    def password(self):
        if self._password is None:
            self._username, self._password = self._get_ru_user_and_password()
        return self._password

    @password.setter
    def password(self, value):
        self._password = value

    @property
    def init_username(self):
        if self._init_username is None:
            try:
                self._init_username = self._init_ru.default_ssh_connection_details.username
                if type(self._init_username) is dict:
                    self._init_username = list(self._init_username.values())[-1]
            except AttributeError:
                raise MissingUsernameInRuObjectError(
                    f"Username is missing in RU object for RU with serial number {self.serial_number}"
                )
        return self._init_username

    @property
    def init_password(self):
        if self._init_password is None:
            try:
                self._init_password = self._init_ru.default_ssh_connection_details.password
                if type(self._init_password) is dict:
                    self._init_password = list(self._init_password.values())[-1]
            except AttributeError:
                raise MissingPasswordInRuObjectError(
                    f"Password is missing in RU object for RU with serial number {self.serial_number}"
                )
        return self._init_password

    @property
    def switch_commands(self):
        if self.radio_family:
            return self._connected_rmod[self.radio_family].switch_commands

    def _set_next_slave_node_id(self):
        if self._current_switch_slave_node_id is None:
            self._set_starting_switch_slave_node_id()
        elif not self.freeze_slave_node:
            self._set_next_slave_node_id_round_robin()

    @property
    def current_switch_slave_node_id(self):
        if self._current_switch_slave_node_id is None:
            self._set_next_slave_node_id()
        return self._current_switch_slave_node_id

    def _set_starting_switch_slave_node_id(self):
        if self.radio_family and self._connected_rmod[self.radio_family].switch_commands:
            self._current_switch_slave_node_id = random.randint(1, len(self.switch_commands) - 1)
            if self._custom_setup:
                default_slave = "switch_slave_node_id"
                self._current_switch_slave_node_id = self._custom_setup.get(ALL_RMODS, {}).get(
                    default_slave, self._current_switch_slave_node_id
                )
                if self._custom_setup.get(self.serial_number, {}).get(default_slave):
                    self._current_switch_slave_node_id = self._custom_setup.get(self.serial_number).get(default_slave)

    def _set_next_slave_node_id_round_robin(self):
        self._current_switch_slave_node_id += 1
        if self._current_switch_slave_node_id >= len(self.switch_commands):
            self._current_switch_slave_node_id = 1

    @property
    def default_slave_node_switch_cmd(self):
        if self.radio_family and self._connected_rmod[self.radio_family].switch_commands:
            try:
                current_cmd = self._connected_rmod[self.radio_family].switch_commands[self.current_switch_slave_node_id]
                self._set_next_slave_node_id()
                return current_cmd
            except IndexError:
                pass
        return None

    @property
    def master_node_switch_cmd(self):
        master_node_id_on_cmds_list = 0
        if self.radio_family and self._connected_rmod[self.radio_family].switch_commands:
            return self._connected_rmod[self.radio_family].switch_commands[master_node_id_on_cmds_list]
        return None

    @property
    def master_node_ids(self):
        if self._master_node_id is None:
            if self.radio_family:
                self._master_node_id = self._connected_rmod[self.radio_family].master_node_ids
        return self._master_node_id

    @property
    def output_switch_seconds(self):
        if self._output_switch_seconds is None and self.radio_family:
            self._output_switch_seconds = self._connected_rmod[self.radio_family].node_switch_time
            if self._custom_setup:
                switch_time = "node_switch_seconds"
                self._output_switch_seconds = self._custom_setup.get(ALL_RMODS, {}).get(
                    switch_time, self._output_switch_seconds
                )
                if self._custom_setup.get(self.serial_number, {}).get(switch_time):
                    self._output_switch_seconds = self._custom_setup.get(self.serial_number).get(switch_time)
        return self._output_switch_seconds

    @property
    def switch_nodes(self):
        switch_nodes = "switch_nodes"
        if self._custom_setup:
            self._switch_nodes = self._custom_setup.get(ALL_RMODS, {}).get(switch_nodes, self._switch_nodes)
            if self._custom_setup.get(self.serial_number, {}).get(switch_nodes) is not None:
                self._switch_nodes = self._custom_setup.get(self.serial_number).get(switch_nodes)
        return self._switch_nodes

    @switch_nodes.setter
    def switch_nodes(self, value):
        self._switch_nodes = value

    @property
    def freeze_slave_node(self):
        freeze_node = "freeze_slave_node_switch"
        if self._custom_setup:
            self._freeze_slave_node = self._custom_setup.get(ALL_RMODS, {}).get(freeze_node, self._freeze_slave_node)
            if self._custom_setup.get(self.serial_number, {}).get(freeze_node) is not None:
                self._freeze_slave_node = self._custom_setup.get(self.serial_number).get(freeze_node)
        return self._freeze_slave_node

    @property
    def preserve_flags(self):
        preserve_flags = "preserve_flags"
        if self._custom_setup:
            self._preserve_flags = self._custom_setup.get(ALL_RMODS, {}).get(preserve_flags, self._preserve_flags)
            if self._custom_setup.get(self.serial_number, {}).get(preserve_flags) is not None:
                self._preserve_flags = self._custom_setup.get(self.serial_number).get(preserve_flags)
        return self._preserve_flags

    @property
    def commands_after_connect(self):
        commands = "send_commands_after_connect"
        if self._custom_setup:
            self._commands_after_connect = self._custom_setup.get(ALL_RMODS, {}).get(commands)
            if self._custom_setup.get(self.serial_number, {}).get(commands):
                self._commands_after_connect = self._custom_setup.get(self.serial_number).get(commands)
        return self._commands_after_connect

    @property
    def commands_after_login_master(self):
        commands = "send_commands_after_login_master"
        if self._custom_setup:
            self._commands_after_login_master = self._custom_setup.get(ALL_RMODS, {}).get(commands)
            if self._custom_setup.get(self.serial_number, {}).get(commands):
                self._commands_after_login_master = self._custom_setup.get(self.serial_number).get(commands)
        return self._commands_after_login_master

    @property
    def commands_after_login_slave(self):
        commands = "send_commands_after_login_slave"
        if self._custom_setup:
            self._commands_after_login_slave = self._custom_setup.get(ALL_RMODS, {}).get(commands)
            if self._custom_setup.get(self.serial_number, {}).get(commands):
                self._commands_after_login_slave = self._custom_setup.get(self.serial_number).get(commands)
        return self._commands_after_login_slave

    @property
    def auto_snapshot_on_fault(self):
        auto_snapshot = "auto_snapshot_on_fault"
        if self._custom_setup:
            self._auto_snapshot = self._custom_setup.get(ALL_RMODS, {}).get(auto_snapshot, self._auto_snapshot)
            if self._custom_setup.get(self.serial_number, {}).get(auto_snapshot) is not None:
                self._auto_snapshot = self._custom_setup.get(self.serial_number).get(auto_snapshot)
        return self._auto_snapshot

    @property
    def critical_faults(self):
        critical_faults = "critical_faults_to_snapshot_list"
        if self._custom_setup:
            self._critical_faults = self._custom_setup.get(ALL_RMODS, {}).get(critical_faults, self._critical_faults)
            if self._custom_setup.get(self.serial_number, {}).get(critical_faults) is not None:
                self._critical_faults = self._custom_setup.get(self.serial_number).get(critical_faults)
        return self._critical_faults

    @property
    def normal_faults(self):
        normal_faults = "normal_faults_to_snapshot_dict"
        if self._custom_setup:
            self._normal_faults = self._custom_setup.get(ALL_RMODS, {}).get(normal_faults, self._normal_faults)
            if self._custom_setup.get(self.serial_number, {}).get(normal_faults) is not None:
                self._normal_faults = self._custom_setup.get(self.serial_number).get(normal_faults)
        return self._normal_faults

    @property
    def fh_interface(self):
        fh_interface = "fh_interface"
        if self._custom_setup:
            self._fh_interface = self._custom_setup.get(ALL_RMODS, {}).get(fh_interface, self._fh_interface)
            if self._custom_setup.get(self.serial_number, {}).get(fh_interface) is not None:
                self._fh_interface = self._custom_setup.get(self.serial_number).get(fh_interface)
        return self._fh_interface

    @property
    def proxy_vm_credentials(self):
        proxy_vm = "proxy_vm"
        if (
            self._proxy_vm_credentials is None
            and self._custom_setup
            and self._custom_setup.get(self.serial_number, {}).get(proxy_vm)
        ):
            self._proxy_vm_credentials = self._custom_setup.get(self.serial_number).get(proxy_vm)
        return self._proxy_vm_credentials

    @proxy_vm_credentials.setter
    def proxy_vm_credentials(self, value):
        self._proxy_vm_credentials = value

    def _read_rmod_data(self):
        if self._custom_yaml_setup:
            with open(self._custom_yaml_setup) as yml_file:
                return safe_load(yml_file)
        return None

    def _get_ru_user_and_password(self):
        tl_info = info()
        legacy_root_credentials = "root", ""
        sw_line = tl_info.get_ru_sw_line(radio_type=self.radio_type, fh_interface=self.fh_interface)
        for username in ["serviceuser", "toor4nsn"]:
            try:
                return username, tl_info.get_ru_password(username=username, by_sw_line=sw_line)
            except UserNotDefinedForSWLine:
                pass
        return legacy_root_credentials
